// 1. Connect sofort senden
node.send([{topic: "connect", payload: ""}, null]);
// 2. Read nach 10s (warten auf Verbindung)
setTimeout(function() {
    node.send([null, {topic: "fff1", payload: ""}]);
}, 10000);

// Parse Gas-O-Meter2 Custom Characteristic 0xFFF1
// Format: {"p":12345,"bv":3910,"bp":85,"bl":0}

let data = {};

try {
    let raw = msg.payload;
    if (typeof raw === 'object' && raw.fff1) {
        raw = raw.fff1;
    }
    if (Buffer.isBuffer(raw)) {
        raw = raw.toString('utf8');
    }
    if (typeof raw === 'string') {
        data = JSON.parse(raw);
    } else if (typeof raw === 'object' && raw !== null && !Buffer.isBuffer(raw)) {
        data = raw;
    }

    msg.payload = {
        gas_counter: data.p || 0,
        gas_m3: (data.p || 0) / 100,
        battery: data.bp || 0,
        battery_voltage_mv: data.bv || 0,
        battery_low: (data.bl || 0) === 1,
        firmware_version: msg.firmware || 'unknown',
        timestamp: new Date().toISOString()
    };

    return msg;
} catch (error) {
    node.error('Parse Error: ' + error.message, msg);
    return null;
}

// Optional: Datenbank-Integration
// TODO: node-red-node-sqlite oder node-red-contrib-influxdb
return msg;

var enable = msg.payload;
var stateTopic = 'gas-o-meter2/data';
var device = {
    identifiers: ['gas_o_meter2'],
    name: 'Gas-O-Meter2',
    manufacturer: 'Custom',
    model: 'Gas-O-Meter2 BLE'
};

var configs = [
    {
        topic: 'homeassistant/sensor/gas_o_meter2_gas/config',
        payload: {
            name: 'Gas Counter',
            unique_id: 'gas_o_meter2_gas',
            state_topic: stateTopic,
            value_template: '{{ value_json.gas_m3 }}',
            unit_of_measurement: 'm\u00b3',
            device_class: 'gas',
            state_class: 'total_increasing',
            icon: 'mdi:meter-gas',
            device: device
        }
    },
    {
        topic: 'homeassistant/sensor/gas_o_meter2_battery/config',
        payload: {
            name: 'Battery',
            unique_id: 'gas_o_meter2_battery',
            state_topic: stateTopic,
            value_template: '{{ value_json.battery }}',
            unit_of_measurement: '%',
            device_class: 'battery',
            state_class: 'measurement',
            icon: 'mdi:battery',
            device: device
        }
    },
    {
        topic: 'homeassistant/sensor/gas_o_meter2_voltage/config',
        payload: {
            name: 'Battery Voltage',
            unique_id: 'gas_o_meter2_voltage',
            state_topic: stateTopic,
            value_template: '{{ value_json.battery_voltage_mv }}',
            unit_of_measurement: 'mV',
            device_class: 'voltage',
            state_class: 'measurement',
            icon: 'mdi:flash',
            device: device
        }
    },
    {
        topic: 'homeassistant/binary_sensor/gas_o_meter2_battery_low/config',
        payload: {
            name: 'Battery Low',
            unique_id: 'gas_o_meter2_battery_low',
            state_topic: stateTopic,
            value_template: '{{ value_json.battery_low }}',
            payload_on: true,
            payload_off: false,
            device_class: 'battery',
            icon: 'mdi:battery-alert',
            device: device
        }
    },
    {
        topic: 'homeassistant/sensor/gas_o_meter2_firmware/config',
        payload: {
            name: 'Firmware',
            unique_id: 'gas_o_meter2_firmware',
            state_topic: stateTopic,
            value_template: '{{ value_json.firmware_version }}',
            icon: 'mdi:information',
            entity_category: 'diagnostic',
            device: device
        }
    }
];

for (var i = 0; i < configs.length; i++) {
    var out = {
        topic: configs[i].topic,
        payload: enable ? JSON.stringify(configs[i].payload) : '',
        retain: true
    };
    node.send(out);
}

node.status({text: enable ? 'AN (' + configs.length + ' Entities)' : 'AUS (entfernt)'});
return null;
